const lesson3BTNC=[{"file":"Q2B3.NC1.MP3","title":"Nâng cao 1","key":["C","E","D","B","A"],"transcript":["我的钱包不见了，你可以帮我找一下吗？","我想给妈妈打个电话，可以借你的手机用一下吗？","这本书我看完了，现在还给你，谢谢！","我的电脑没电了，可以用一下你的吗？只要十分钟。","我忘了带现金，你可以先借我一百块吗？明天还你。"],"questions":[["什么东西不见了？",["手机","钱包","书"],1],["他想给谁打电话？",["妈妈","老师","朋友"],0],["他说要还什么？",["电脑","手机","书"],2],["他想用电脑多长时间？",["五分钟","十分钟","半个小时"],1],["他想借多少钱？",["一百块","十块","一千块"],0]]},{"file":"Q2B3.NC2.MP3","title":"Nâng cao 2","key":["C","D","E","A","B"],"transcript":["女：请问，去最近的邮局怎么走？\n男：从这儿直走，第二个路口左转就到了。","男：你的耳机音质真好，可以借我听一首歌吗？\n女：当然可以，给你。","女：糟糕，我忘带充电宝了，手机快没电了。\n男：别担心，我带了，借给你用。","男：这个二维码我怎么扫不出来？\n女：让我看看。哦，你的网络好像不太好。","女：你的笔真好写，可以借我写个地址吗？就写一下。\n男：没问题，拿去用吧。"],"questions":[["去邮局在哪个路口左转？",["第一个","第二个","第三个"],1],["他想借耳机做什么？",["听一首歌","打电话","上课"],0],["她忘带什么？",["现金","笔","充电宝"],2],["二维码扫不出来，可能是什么问题？",["没有电","网络不好","忘带手机"],1],["她借笔想写什么？",["名字","作业","地址"],2]]},{"file":"Q2B3.NC3.MP3","title":"Nâng cao 3","key":["A","C","B","B","C"],"transcript":["男：阿龙，你可以帮我拍张照片吗？我的手机相机坏了。\n女：好啊，你站到那儿去。一、二、三，好了！","男：小云，你记得陈老师的电子邮箱吗？我想给他发作业。\n女：我记得，我找一下……找到了，我念给你听。","男：我的车钥匙好像落在会议室了，你可以陪我回去找一下吗？\n女：现在会议室可能锁门了。你可以先去前台问问保安。","男：这份文件需要打印十份，下午开会用。打印室的打印机好像坏了。\n女：你可以用我们部门的打印机，我帮你设置一下。","男：我自行车胎没气了，附近有修车店吗？\n女：有，出校门右转就有一家。你需要打气筒吗？我宿舍有一个可以借你。"],"questions":[["他为什么请别人帮忙拍照？",["手机相机坏了","没有带笔","想找钥匙"],0],["他想要陈老师的什么？",["手机号","电子邮箱","地址"],1],["钥匙可能落在哪里？",["教室","宿舍","会议室"],2],["文件要打印几份？",["五份","十份","十五份"],1],["修车店怎么走？",["出校门右转","出校门左转","一直往前走"],0]]}];
